IMP(glTexGenivOES) { T(glTexGenivOES); if (dgl_glTexGeniv) { u32 c0 = r0 == 0x8D60 ? 0x2000 : r0, c1 = r0 == 0x8D60 ? 0x2002 : r0; for (u32 c = c0; c <= c1; c++) { dgl_glTexGeniv(c, r1, P(r2)); if (r0 != 0x8D60) break; } } RET(0); }

// ---- ETC1: desktop GPUs do not support it, so it is decoded here and uploaded as plain RGB
static void etc1_block(const u8* b, u8* out /* 4x4 RGB, row-major */) {
    static const int mod[8][4] = {{2, 8, -2, -8}, {5, 17, -5, -17}, {9, 29, -9, -29}, {13, 42, -13, -42},
                                  {18, 60, -18, -60}, {24, 80, -24, -80}, {33, 106, -33, -106}, {47, 183, -47, -183}};
    int diff = (b[3] >> 1) & 1, flip = b[3] & 1, c1[3], c2[3];
    if (diff) {
        for (int i = 0; i < 3; i++) {
            int base = b[i] >> 3, d = b[i] & 7; if (d & 4) d -= 8;
            int v2 = base + d; if (v2 < 0) v2 = 0; if (v2 > 31) v2 = 31;
            c1[i] = (base << 3) | (base >> 2); c2[i] = (v2 << 3) | (v2 >> 2);
        }
    } else for (int i = 0; i < 3; i++) { c1[i] = (b[i] >> 4) * 17; c2[i] = (b[i] & 15) * 17; }
    int t1 = (b[3] >> 5) & 7, t2 = (b[3] >> 2) & 7;
    u32 msb = (b[4] << 8) | b[5], lsb = (b[6] << 8) | b[7];
    for (int x = 0; x < 4; x++) for (int y = 0; y < 4; y++) {
        int idx = x * 4 + y, second = flip ? (y >= 2) : (x >= 2);
        int pm = (((msb >> idx) & 1) << 1) | ((lsb >> idx) & 1);
        int m = mod[second ? t2 : t1][pm]; const int* c = second ? c2 : c1;
        for (int k = 0; k < 3; k++) { int v = c[k] + m; out[(y * 4 + x) * 3 + k] = (u8)(v < 0 ? 0 : v > 255 ? 255 : v); }
    }
}
static u8* etc1_decode(const u8* src, int w, int h) {
    u8* dst = malloc((size_t)w * h * 3); int bw = (w + 3) / 4, bh = (h + 3) / 4;
    for (int by = 0; by < bh; by++) for (int bx = 0; bx < bw; bx++) {
        u8 blk[48]; etc1_block(src + ((size_t)by * bw + bx) * 8, blk);
        for (int y = 0; y < 4 && by * 4 + y < h; y++) for (int x = 0; x < 4 && bx * 4 + x < w; x++)
            memcpy(dst + ((size_t)(by * 4 + y) * w + bx * 4 + x) * 3, blk + (y * 4 + x) * 3, 3);
    }
    return dst;
}
#include "texture_hd.h"
IMP(glCompressedTexImage2D) {
    T(glCompressedTexImage2D);
    u32 target = r0, level = r1, fmt = r2, w = r3, h = W(4), size = W(6); const u8* data = (const u8*)P(W(7));
    ds_sky_diag_image(target,w,h);
    if(ds_hd_image(target,level,fmt,w,h,W(5),fmt,0,data,size,1))RET(0);
    if (fmt == 0x8D64) {
        if (dgl_glTexImage2D && data) {
            u8* rgb = etc1_decode(data, (int)w, (int)h);
            dgl_glPixelStorei(0x0CF5, 1);
            dgl_glTexImage2D(target, (s32)level, 0x1907, (s32)w, (s32)h, 0, 0x1907, 0x1401, rgb);
            dgl_glPixelStorei(0x0CF5, (s32)g_unpack_align); free(rgb);
        }
    } else printf("   [gl] unsupported compressed texture format %#x (%ux%u, %u bytes)\n", fmt, w, h, size);
    RET(0);
}
IMP(glCompressedTexSubImage2D) {
    T(glCompressedTexSubImage2D);
    ds_hd_subimage(r0);
    u32 target = r0, level = r1, xo = r2, yo = r3, w = W(4), h = W(5), fmt = W(6); const u8* data = (const u8*)P(W(8));
    if (fmt == 0x8D64) {
        if (dgl_glTexSubImage2D && data) {
            u8* rgb = etc1_decode(data, (int)w, (int)h);
            dgl_glPixelStorei(0x0CF5, 1);
            dgl_glTexSubImage2D(target, (s32)level, (s32)xo, (s32)yo, (s32)w, (s32)h, 0x1907, 0x1401, rgb);
            dgl_glPixelStorei(0x0CF5, (s32)g_unpack_align); free(rgb);
        }
    } else printf("   [gl] unsupported compressed sub-image format %#x\n", fmt);
    RET(0);
}
